    <form
      onSubmit={(e) => {
        e.preventDefault();
        onSubmit({ name, date });
      }}
    >
      <label>
        Name <input value={name} onChange={(e) => setName(e.target.value)} />
      </label>
      <label>
        Date <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
      </label>
      <button type="submit">Save</button>
    </form>
  );
}
```

